export type TranslationKey = keyof typeof translations.en;
type LanguageContextValue = {
    language: Language;
    setLanguage: (language: Language) => void;
    t: (key: TranslationKey) => string;
};

const STORAGE_KEY = 'purity-language';
const isLanguage = (value: string | null): value is Language => value === 'en' || value === 'fr' || value === 'hi';

const detectLanguage = (): Language => {
    if (typeof window === 'undefined') return 'en';
    let saved: string | null = null;
    try {
        saved = window.localStorage.getItem(STORAGE_KEY);
    } catch {
        // Private browsing policies may deny storage; browser detection still works.
    }
    if (isLanguage(saved)) return saved;
    const browserLanguages = [window.navigator.language, ...(window.navigator.languages || [])].map(value => value.toLowerCase());
    if (browserLanguages.some(value => value.startsWith('fr'))) return 'fr';
    if (browserLanguages.some(value => value.startsWith('hi'))) return 'hi';
    return 'en';
};

const LanguageContext = createContext<LanguageContextValue | null>(null);

export const LanguageProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [language, setLanguageState] = useState<Language>(detectLanguage);

    const setLanguage = (nextLanguage: Language) => {
        setLanguageState(nextLanguage);
        try {
            window.localStorage.setItem(STORAGE_KEY, nextLanguage);
        } catch {
            // The in-memory selection remains active for this session.
        }
    };

    useEffect(() => {
        document.documentElement.lang = language;
        document.documentElement.dir = 'ltr';
        document.documentElement.setAttribute('data-language', language);
    }, [language]);

    const value = useMemo(() => ({
        language,
        setLanguage,
        t: (key: TranslationKey) => translations[language][key] || translations.en[key],
    }), [language]);

    return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
};

export const useLanguage = (): LanguageContextValue => {
    const context = useContext(LanguageContext);
    if (!context) throw new Error('useLanguage must be used inside LanguageProvider');
    return context;
};
